contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount2)); require(amount <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount == 10 && amount2 == 10);
        require(address(this).balance >= amount + amount2);
        c.play{value: amount}(); if (__ESBMC_reverted()) return;
        c.play{value: amount2}(); if (__ESBMC_reverted()) return;
        assert((c.pot() == 0 || c.pot() == 10 || c.pot() == 20) && address(c).balance >= c.pot());
    }
    receive() external payable {}
}

