// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount, uint256 amount2) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        amount2 = 10;
        vm.assume(address(this).balance >= amount + amount2);
        try c.play{value: amount}() {} catch { return; }
        try c.play{value: amount2}() {} catch { return; }
        assertTrue((c.pot() == 0 || c.pot() == 10 || c.pot() == 20) && address(c).balance >= c.pot());
    }

    function testFuzz_run(uint256 amount, uint256 amount2) public {
        _run(amount, amount2);
    }

    receive() external payable {}
}
